import { ShipRelayClient } from "./shipRelayClient";
import { CarrierError, CarrierErrorKind } from "./errors";

export interface Address {
  name: string;
  line1: string;
  city: string;
  postalCode: string;
  country: string;
}

export interface Parcel {
  weightGrams: number;
  lengthCm: number;
  widthCm: number;
  heightCm: number;
}

export interface Quote {
  serviceCode: string;
  amountCents: number;
  currency: string;
  estimatedDays: number | null;
}

export interface PurchasedLabel {
  trackingNumber: string;
  labelUrl: string;
  costCents: number;
}

export interface ShippingCarrier {
  quote(from: Address, to: Address, parcel: Parcel): Promise<Quote[]>;
  buyLabel(orderId: string, quote: Quote, from: Address, to: Address, parcel: Parcel): Promise<PurchasedLabel>;
}

interface SrRate {
  service: string;
  total: string;
  currency: string;
  transit_days?: number;
}

interface SrShipment {
  tracking_code: string;
  label: { url: string };
  charged: { amount: string };
}

export class ShipRelayCarrier implements ShippingCarrier {
  constructor(private readonly client: ShipRelayClient) {}

  async quote(from: Address, to: Address, parcel: Parcel): Promise<Quote[]> {
    const res = await this.client.request<{ rates: SrRate[] }>("POST", "/v2/rates", {
      origin: toSrAddress(from),
      destination: toSrAddress(to),
      parcel: toSrParcel(parcel),
    });
    return res.rates.map((r) => ({
      serviceCode: r.service,
      amountCents: toCents(r.total),
      currency: r.currency,
      estimatedDays: r.transit_days ?? null,
    }));
  }

  async buyLabel(orderId: string, quote: Quote, from: Address, to: Address, parcel: Parcel): Promise<PurchasedLabel> {
    const res = await this.client.request<SrShipment>("POST", "/v2/shipments", {
      reference: orderId,
      service: quote.serviceCode,
      origin: toSrAddress(from),
      destination: toSrAddress(to),
      parcel: toSrParcel(parcel),
    });
    const costCents = toCents(res.charged.amount);
    if (costCents > quote.amountCents) {
      throw new CarrierError(
        CarrierErrorKind.Rejected,
        `label for ${orderId} cost ${costCents} exceeds quoted ${quote.amountCents}`,
      );
    }
    return { trackingNumber: res.tracking_code, labelUrl: res.label.url, costCents };
  }
}

function toSrAddress(a: Address) {
  return { name: a.name, street1: a.line1, city: a.city, zip: a.postalCode, country: a.country.toUpperCase() };
}

function toSrParcel(p: Parcel) {
  return { weight_oz: Math.ceil(p.weightGrams / 28.35), length_in: p.lengthCm / 2.54, width_in: p.widthCm / 2.54, height_in: p.heightCm / 2.54 };
}

function toCents(decimal: string): number {
  const [whole, frac = ""] = decimal.split(".");
  return Number(whole) * 100 + Number((frac + "00").slice(0, 2));
}

import { randomUUID } from "crypto";
import { CarrierError, CarrierErrorKind } from "./errors";

export interface ShipRelayConfig {
  baseUrl: string;
  apiKey: string;
  timeoutMs: number;
  maxAttempts: number;
}

type HttpMethod = "GET" | "POST";

const RETRYABLE_STATUS = new Set([429, 502, 503, 504]);

export class ShipRelayClient {
  constructor(private readonly cfg: ShipRelayConfig) {}

  async request<T>(method: HttpMethod, path: string, body?: unknown): Promise<T> {
    let lastError: CarrierError | undefined;

    for (let attempt = 1; attempt <= this.cfg.maxAttempts; attempt++) {
      const headers: Record<string, string> = {
        Authorization: `Bearer ${this.cfg.apiKey}`,
        "Content-Type": "application/json",
      };
      if (method === "POST") {
        headers["Idempotency-Key"] = randomUUID();
      }

      try {
        const res = await fetch(`${this.cfg.baseUrl}${path}`, {
          method,
          headers,
          body: body === undefined ? undefined : JSON.stringify(body),
          signal: AbortSignal.timeout(this.cfg.timeoutMs),
        });

        if (res.ok) {
          return (await res.json()) as T;
        }

        const text = await res.text();
        lastError = CarrierError.fromStatus(res.status, text);
        if (!RETRYABLE_STATUS.has(res.status)) {
          throw lastError;
        }
        const retryAfter = Number(res.headers.get("Retry-After"));
        await sleep(Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter * 1000 : backoff(attempt));
      } catch (err) {
        if (err instanceof CarrierError && err.kind !== CarrierErrorKind.Unavailable) {
          throw err;
        }
        lastError =
          err instanceof CarrierError
            ? err
            : new CarrierError(CarrierErrorKind.Unavailable, `ShipRelay ${method} ${path} failed`, err);
        await sleep(backoff(attempt));
      }
    }

    throw lastError ?? new CarrierError(CarrierErrorKind.Unavailable, "ShipRelay: no attempts made");
  }
}

function backoff(attempt: number): number {
  const base = 200 * 2 ** (attempt - 1);
  return base + Math.floor(Math.random() * base);
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export enum CarrierErrorKind {
  InvalidAddress = "invalid_address",
  Unauthorized = "unauthorized",
  RateLimited = "rate_limited",
  Unavailable = "unavailable",
  Rejected = "rejected",
}

export class CarrierError extends Error {
  constructor(
    readonly kind: CarrierErrorKind,
    message: string,
    readonly cause?: unknown,
  ) {
    super(message);
    this.name = "CarrierError";
  }

  static fromStatus(status: number, body: string): CarrierError {
    const snippet = body.slice(0, 200);
    if (status === 401 || status === 403) {
      return new CarrierError(CarrierErrorKind.Unauthorized, `ShipRelay auth failed (${status})`);
    }
    if (status === 422) {
      return new CarrierError(CarrierErrorKind.InvalidAddress, `ShipRelay rejected address: ${snippet}`);
    }
    if (status === 429 || status >= 500) {
      return new CarrierError(CarrierErrorKind.Unavailable, `ShipRelay unavailable (${status})`);
    }
    return new CarrierError(CarrierErrorKind.Rejected, `ShipRelay error ${status}: ${snippet}`);
  }
}
